// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title EscrowPayment
 * @notice Agent 间托管支付合约 —— 解决"谁先付钱"的信任问题
 *
 * 流程：
 *   1. Consumer（买方）调用 requestService()，支付费用，资金锁在合约里
 *   2. 合约触发 ServiceRequested 事件 → Provider（卖方）监听到后执行服务
 *   3. Provider 调用 deliverResult()，提交数据哈希上链作为凭证
 *   4. Consumer 验证数据 → 调用 confirmDelivery() → 合约放款给 Provider
 *      Consumer 觉得数据有问题 → 调用 dispute() → 进入仲裁流程
 *      超时未操作 → Consumer 可调用 refund() 退款
 *
 * 安全设计：
 *   - CEI 模式（Check-Effects-Interactions）：先检查状态，再更新状态，最后转账
 *   - ReentrancyGuard：防止重入攻击
 *   - pull over push：放款时让收款方主动取钱，而不是合约 push 转账
 */
contract EscrowPayment {
    // ── 状态常量 ──
    enum RequestState { Pending, Delivered, Confirmed, Disputed, Refunded }

    // ── 数据结构 ──
    struct PaymentRequest {
        uint256 id;              // 请求 ID
        address consumer;        // 买方（消费方 Agent）
        address provider;        // 卖方（供应方 Agent）
        uint256 amount;          // 支付金额
        bytes32 dataHash;        // Provider 交付的数据哈希（用于验证数据完整性）
        RequestState state;      // 当前状态
        uint256 deadline;        // 超时时间戳（Consumer 在此之前需确认，否则可退款）
        uint256 serviceId;       // 关联的 ServiceRegistry 服务 ID
    }

    // 所有支付请求
    PaymentRequest[] public requests;

    // 防止重入攻击的锁
    bool private locked;

    // 引用 ServiceRegistry 合约地址
    address public serviceRegistry;

    // 超时时间（默认 30 分钟）
    uint256 public constant DEFAULT_TIMEOUT = 30 minutes;

    // 事件
    event ServiceRequested(
        uint256 indexed requestId,
        address indexed consumer,
        address indexed provider,
        uint256 amount,
        uint256 serviceId,
        uint256 deadline
    );
    event ResultDelivered(uint256 indexed requestId, bytes32 dataHash);
    event DeliveryConfirmed(uint256 indexed requestId);
    event DisputeRaised(uint256 indexed requestId);
    event Refunded(uint256 indexed requestId);

    // ── 修饰器 ──
    modifier noReentrancy() {
        require(!locked, "reentrancy not allowed");
        locked = true;
        _;
        locked = false;
    }

    // ── 构造函数 ──
    constructor(address _serviceRegistry) {
        serviceRegistry = _serviceRegistry;
    }

    // ── 核心流程 ──

    /**
     * @notice Step 1: Consumer 请求服务并支付费用
     * @param _provider 供应商地址
     * @param _serviceId 服务 ID
     */
    function requestService(
        address _provider,
        uint256 _serviceId
    ) external payable noReentrancy {
        require(msg.value > 0, "amount must be > 0");
        require(_provider != address(0), "invalid provider address");
        require(_provider != msg.sender, "cannot pay self");

        uint256 requestId = requests.length;
        requests.push(PaymentRequest({
            id: requestId,
            consumer: msg.sender,
            provider: _provider,
            amount: msg.value,
            dataHash: bytes32(0),
            state: RequestState.Pending,
            deadline: block.timestamp + DEFAULT_TIMEOUT,
            serviceId: _serviceId
        }));

        emit ServiceRequested(
            requestId,
            msg.sender,
            _provider,
            msg.value,
            _serviceId,
            block.timestamp + DEFAULT_TIMEOUT
        );
    }

    /**
     * @notice Step 2: Provider 交付结果，提交数据哈希上链存证
     * @param _requestId 请求 ID
     * @param _dataHash 交付数据的哈希（keccak256 后）
     *
     * 注意：这里只存哈希不上传原始数据（链上存储太贵）
     *       原始数据通过链下通道（HTTP/MCP）传递
     *       dataHash 用于 Consumer 验证数据是否被篡改
     */
    function deliverResult(uint256 _requestId, bytes32 _dataHash)
        external
        noReentrancy
    {
        PaymentRequest storage req = requests[_requestId];

        require(msg.sender == req.provider, "only provider can deliver");
        require(req.state == RequestState.Pending, "invalid state for delivery");
        require(_dataHash != bytes32(0), "data hash cannot be empty");

        req.state = RequestState.Delivered;
        req.dataHash = _dataHash;

        emit ResultDelivered(_requestId, _dataHash);
    }

    /**
     * @notice Step 3: Consumer 确认数据无误，合约直接放款给 Provider
     * @param _requestId 请求 ID
     *
     * 安全：遵循 CEI（Check-Effects-Interactions）模式
     *       先更新状态为 Confirmed，再执行转账
     *       noReentrancy 修饰器防止重入攻击
     */
    function confirmDelivery(uint256 _requestId) external noReentrancy {
        PaymentRequest storage req = requests[_requestId];

        require(msg.sender == req.consumer, "only consumer can confirm");
        require(req.state == RequestState.Delivered, "provider has not delivered");

        req.state = RequestState.Confirmed;

        // 放款给 Provider
        (bool sent, ) = payable(req.provider).call{value: req.amount}("");
        require(sent, "payment failed");

        emit DeliveryConfirmed(_requestId);
    }

    /**
     * @notice Consumer 对数据质量不满，发起争议
     * @param _requestId 请求 ID
     *
     * 当前版本：争议后资金暂时冻结，需要人工仲裁
     * 可扩展：可以接入 DAO 投票或预设仲裁者
     */
    function dispute(uint256 _requestId) external noReentrancy {
        PaymentRequest storage req = requests[_requestId];

        require(msg.sender == req.consumer, "only consumer can dispute");
        require(
            req.state == RequestState.Delivered,
            "only delivered state can dispute"
        );

        req.state = RequestState.Disputed;

        emit DisputeRaised(_requestId);
    }

    /**
     * @notice 超时退款 —— Provider 超时未交付，Consumer 拿回资金
     * @param _requestId 请求 ID
     */
    function refund(uint256 _requestId) external noReentrancy {
        PaymentRequest storage req = requests[_requestId];

        require(msg.sender == req.consumer, "only consumer can refund");
        require(
            req.state == RequestState.Pending,
            "only pending state can refund"
        );
        require(block.timestamp > req.deadline, "not yet expired");

        req.state = RequestState.Refunded;

        (bool sent, ) = payable(req.consumer).call{value: req.amount}("");
        require(sent, "refund failed");

        emit Refunded(_requestId);
    }

    // ── 查询 ──

    function getRequestCount() external view returns (uint256) {
        return requests.length;
    }

    function getRequest(uint256 _requestId)
        external
        view
        returns (PaymentRequest memory)
    {
        require(_requestId < requests.length, "request does not exist");
        return requests[_requestId];
    }

    /**
     * @notice 查询某个 Consumer 的所有请求
     */
    function getConsumerRequests(address _consumer)
        external
        view
        returns (PaymentRequest[] memory)
    {
        uint256 count = requests.length;
        uint256 consumerCount = 0;

        for (uint256 i = 0; i < count; i++) {
            if (requests[i].consumer == _consumer) {
                consumerCount++;
            }
        }

        PaymentRequest[] memory result = new PaymentRequest[](consumerCount);
        uint256 index = 0;
        for (uint256 i = 0; i < count; i++) {
            if (requests[i].consumer == _consumer) {
                result[index] = requests[i];
                index++;
            }
        }
        return result;
    }
}

contracts/Reputation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title Reputation
 * @notice Agent 声誉系统 —— 每次交易完成后 Consumer 给 Provider 打分
 *
 * 目的：帮助 Consumer 选择可信赖的服务提供商
 *       多次低分 → Provider 接不到单子 → 经济惩罚
 */
contract Reputation {

    struct ReputationData {
        uint256 totalRatings;    // 评价总次数
        uint256 sumScores;       // 分数总和
        uint256 completedJobs;   // 完成的订单数
    }

    // provider 地址 → 声誉数据
    mapping(address => ReputationData) public reputations;

    // 每个 Consumer 对每个 Provider 只能评价一次
    mapping(address => mapping(address => bool)) public hasRated;

    event ProviderRated(
        address indexed provider,
        address indexed rater,
        uint256 score,
        uint256 newAverage
    );

    // 无需构造函数参数，评分系统独立于支付合约
    constructor() {}

    /**
     * @notice Consumer 给 Provider 打分（1-5 星）
     * @param _provider 供应商地址
     * @param _score 评分 1-5
     */
    function rateProvider(address _provider, uint256 _score) external {
        require(_score >= 1 && _score <= 5, "score must be 1-5");
        require(!hasRated[msg.sender][_provider], "already rated this provider");
        require(_provider != msg.sender, "cannot self-rate");

        reputations[_provider].totalRatings++;
        reputations[_provider].sumScores += _score;
        reputations[_provider].completedJobs++;

        hasRated[msg.sender][_provider] = true;

        uint256 average = reputations[_provider].sumScores /
            reputations[_provider].totalRatings;

        emit ProviderRated(_provider, msg.sender, _score, average);
    }

    /**
     * @notice 查询供应商的平均评分
     */
    function getRating(address _provider)
        external
        view
        returns (uint256 average, uint256 totalRatings, uint256 completedJobs)
    {
        ReputationData memory r = reputations[_provider];
        if (r.totalRatings == 0) {
            return (0, 0, 0);
        }
        average = r.sumScores / r.totalRatings;
        return (average, r.totalRatings, r.completedJobs);
    }
}

contracts/ServiceRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title ServiceRegistry
 * @notice Agent 服务注册表 —— 供应商在这里发布服务，消费者在这里查找服务
 *
 * 场景：金融数据 Agent 调用 registerService() 发布"财报查询"服务
 *       标价 0.01 ETH/次。股票分析 Agent 调用 getService() 找到它并调用。
 */
contract ServiceRegistry {

    // ── 数据结构 ──

    struct Service {
        uint256 id;             // 服务 ID
        address provider;       // 供应商地址（谁提供的）
        string name;            // 服务名称，如 "financial_report_query"
        string description;     // 服务描述，如 "查询美股上市公司的财报核心指标"
        uint256 price;          // 每次调用的价格（单位：wei）
        bool isActive;          // 是否还在提供
    }

    // 所有服务列表
    Service[] public services;

    // 根据服务名查找活跃服务的索引（用于快速查询）
    mapping(string => uint256[]) private nameToServiceIds;

    // 事件
    event ServiceRegistered(
        uint256 indexed serviceId,
        address indexed provider,
        string name,
        uint256 price
    );
    event ServiceUpdated(uint256 indexed serviceId, uint256 newPrice, bool isActive);

    // ── 供应商操作 ──

    /**
     * @notice 供应商注册一个新服务
     * @param _name 服务名称
     * @param _description 服务描述
     * @param _price 每次调用的价格（wei）
     */
    function registerService(
        string calldata _name,
        string calldata _description,
        uint256 _price
    ) external {
        require(_price > 0, "price must be > 0");

        uint256 serviceId = services.length;
        services.push(Service({
            id: serviceId,
            provider: msg.sender,
            name: _name,
            description: _description,
            price: _price,
            isActive: true
        }));

        nameToServiceIds[_name].push(serviceId);

        emit ServiceRegistered(serviceId, msg.sender, _name, _price);
    }

    /**
     * @notice 供应商更新已有的服务（价格、状态）
     */
    function updateService(
        uint256 _serviceId,
        uint256 _newPrice,
        bool _isActive
    ) external {
        require(_serviceId < services.length, "service does not exist");
        Service storage s = services[_serviceId];
        require(s.provider == msg.sender, "only provider can update");

        s.price = _newPrice;
        s.isActive = _isActive;

        emit ServiceUpdated(_serviceId, _newPrice, _isActive);
    }

    // ── 消费者查询 ──

    /**
     * @notice 根据名称查找所有活跃的服务
     * @return 服务列表 + 对应的供应商地址和价格
     */
    function getService(string calldata _name)
        external
        view
        returns (Service[] memory)
    {
        uint256[] memory ids = nameToServiceIds[_name];
        uint256 count = ids.length;

        // 先统计活跃数量
        uint256 activeCount = 0;
        for (uint256 i = 0; i < count; i++) {
            if (services[ids[i]].isActive) {
                activeCount++;
            }
        }

        // 只返回活跃服务
        Service[] memory result = new Service[](activeCount);
        uint256 index = 0;
        for (uint256 i = 0; i < count; i++) {
            if (services[ids[i]].isActive) {
                result[index] = services[ids[i]];
                index++;
            }
        }
        return result;
    }

    /**
     * @notice 获取某个供应商注册的所有服务
     */
    function getProviderServices(address _provider)
        external
        view
        returns (Service[] memory)
    {
        uint256 count = services.length;
        uint256 providerCount = 0;

        for (uint256 i = 0; i < count; i++) {
            if (services[i].provider == _provider) {
                providerCount++;
            }
        }

        Service[] memory result = new Service[](providerCount);
        uint256 index = 0;
        for (uint256 i = 0; i < count; i++) {
            if (services[i].provider == _provider) {
                result[index] = services[i];
                index++;
            }
        }
        return result;
    }

    function getServiceCount() external view returns (uint256) {
        return services.length;
    }
}

